    /** @return array<string, mixed> */ public function integrationCapabilities(): array { return ['auth'=>['strategy'=>'api_token','legacy_auth_type'=>'api_token','credential_mode'=>'secret','setup_flows'=>['manual_secret'],'requires_browser_for_setup'=>false,'refreshable'=>false,'token_keys'=>[],'notes'=>['Set a Kubernetes API server URL and bearer token with RBAC permissions for the requested operations.']],'host_availability'=>['web'=>['setup_supported'=>true,'runtime_supported'=>true,'setup_mode'=>'manual_secret'],'cli'=>['setup_supported'=>true,'runtime_supported'=>true,'setup_mode'=>'manual_secret','runtime_mode'=>'normal']],'runtime_requirements'=>[],'compatibility'=>['web_setup_supported'=>true,'web_runtime_supported'=>true,'cli_setup_supported'=>true,'cli_runtime_supported'=>true]]; }
    public function appName(): string { return 'kubernetes'; } public function appMeta(): array { return ['label'=>'Kubernetes','description'=>'Cluster resources, workloads, RBAC, networking, storage, autoscaling, policy, and discovery APIs','icon'=>'ph:cube','logo'=>'ph:cube']; }
    public function integrationMeta(): array { return ['name'=>'Kubernetes','description'=>'Manage Kubernetes cluster resources through the official Kubernetes v1.36 OpenAPI surface, including core, apps, batch, RBAC, networking, storage, autoscaling, admission, and policy APIs.','icon'=>'ph:cube','logo'=>'ph:cube','category'=>'data','badge'=>'verified','docs_url'=>'https://kubernetes.io/docs/concepts/overview/kubernetes-api/']; }
    public function configSchema(): array { return [['key'=>'api_token','type'=>'secret','label'=>'Bearer Token','required'=>true],['key'=>'url','type'=>'url','label'=>'API Server URL','placeholder'=>'https://kubernetes.example.test','required'=>true]]; }
    /** @param  array<string, mixed>  $config  Credential and endpoint settings. @return array{success: bool, message?: string, error?: string} */ public function testConnection(array $config): array { $token=(string)($config['api_token']??''); $baseUrl=rtrim((string)($config['url']??''),'/'); if($token===''||$baseUrl==='')return ['success'=>false,'error'=>'Kubernetes API server URL and bearer token are required.']; try{$response=Http::withHeaders(['Authorization'=>'Bearer '.$token,'Accept'=>'application/json'])->timeout(10)->get($baseUrl.'/version'); if(!$response->successful())return ['success'=>false,'error'=>'Kubernetes API returned HTTP '.$response->status().'.']; return ['success'=>true,'message'=>'Connected to Kubernetes at '.$baseUrl.'.'];}catch(\Throwable $e){return ['success'=>false,'error'=>$e->getMessage()];} }
    public function validationRules(): array { return ['api_token'=>'required|string','url'=>'required|url']; } public function credentialFields(): array { return [['key'=>'api_token','type'=>'secret','label'=>'Bearer Token','required'=>true],['key'=>'url','type'=>'url','label'=>'API Server URL','required'=>true]]; }
